			"title": "Automations",
			"body": "export type AutomationTrigger<S extends AnySchema = AnySchema> = \n/** No automatic trigger. The automation is still manually runnable, like every automation. */\n{\n    readonly schedule?: string;\n    readonly trigger?: never;\n} | {\n    /** An additional automatic start when a row changes. Manual invocation remains available. */\n    readonly trigger: {\n        readonly collection: TableName<S>;\n        readonly event: 'created' | 'updated' | 'deleted';\n    };\n    readonly schedule?: never;\n};\n\n/**\n * The capability an authored automation has in addition to the ordinary server API.\n *\n * It is deliberately absent from hooks and remotes. Progress belongs to a durable background run;\n * a hook is part of somebody else's atomic write and must never acquire an I/O checkpoint API that\n * can outlive or partially report that write.\n */\nexport type AutomationApi<S extends AnySchema = DefaultWorkspaceSchema> = Api<S> & {\n    /** Runtime-owned occurrence identity, stable across retries. Use it to key durable receipts. */\n    readonly runId: string;\n    /** Retrieves a bounded public HTTPS page through the host connector, without stored sign-ins. */\n    readonly readUrl: (url: string) => Effect.Effect<import('@norbital-ai/bolt-protocol').WebPage>;\n    /** Bounded GET through this automation's declared connection and managed credential. */\n    readonly connection: {\n        readonly get: (input: {\n            readonly path: string;\n            readonly query?: Readonly<Record<string, string | number | boolean>>;\n        }) => Effect.Effect<import('@norbital-ai/bolt-protocol').IntegrationHttpResponse>;\n    };\n    /** Replaces this run's current progress snapshot and advances its monotonic sequence. */\n    readonly progress: (value: AutomationProgression) => Effect.Effect<void>;\n};\n\nexport type AutomationContext<T extends AutomationTrigger<S>, S extends AnySchema, I extends Schema.Top | undefined = undefined> = {\n    readonly args: AutomationInput<I>;\n    readonly scope: T extends {\n        readonly trigger: {\n            readonly collection: infer N extends TableName<S>;\n        };\n    } ? {\n        readonly incoming_record: SchemaRow<S, N>;\n    } : Readonly<Record<string, unknown>>;\n};\n\nexport interface AutomationDefinition<S extends AnySchema = DefaultWorkspaceSchema, T extends AutomationTrigger<S> = AutomationTrigger<S>, I extends Schema.Top | undefined = undefined, O extends Schema.Top | undefined = undefined, E = never> {\n    readonly trigger: T;\n    readonly spec: Readonly<{\n        readonly description: string;\n        readonly connection?: HttpConnection;\n        /**\n         * The policies this automation runs under — its authority *and* its toolset.\n         *\n         * Required, and required for the reason `envoy()` requires them: an automation that names none\n         * would hold nothing, and the shape that let it hold whatever its trigger held is exactly what\n         * this replaces.\n         */\n        readonly policies: ReadonlyArray<PolicyName>;\n        readonly handler: (api: AutomationApi<S>, context: AutomationContext<T, S, I>) => Effect.Effect<AutomationOutput<O>, E, never> | AutomationOutput<O>;\n    }> & AutomationInputDeclaration<I> & AutomationOutputDeclaration<O>;\n}\n\n/**\n * Public call contract kept distinct from the implementation so declaration emission retains\n * `DefaultWorkspaceSchema`. Each workspace can therefore augment the handler's concrete tables\n * before TypeScript contextually types its incoming record and database API.\n */\ninterface DefineAutomation {\n    <S extends AnySchema = DefaultWorkspaceSchema, const T extends AutomationTrigger<S> = AutomationTrigger<S>, const I extends Schema.Top | undefined = undefined, const O extends Schema.Top | undefined = undefined, E = never>(trigger: ExactAutomationTrigger<T>, spec: AutomationDefinition<S, T, I, O, E>['spec']): AutomationDefinition<S, T, I, O, E>;\n}\n\nexport declare const defineAutomation: DefineAutomation;"
