			"title": "Collections and notifications",
			"body": "/** The declaration `defineCollection` accepts. */\nexport interface CollectionDeclaration<M extends ModelDeclaration = ModelDeclaration, Create extends CollectionOperationDeclaration | undefined = undefined, Update extends CollectionOperationDeclaration | undefined = undefined, Delete extends Readonly<Record<never, never>> | undefined = undefined> {\n    readonly model: M;\n    /** Presence exposes `create`; absent, the collection accepts no direct create. */\n    readonly create?: Create;\n    /** Presence exposes `update`; absent, the collection accepts no direct update. */\n    readonly update?: Update;\n    /** Presence exposes `delete(id)`; a delete has no input and no transform. */\n    readonly delete?: Delete;\n    /** `NoInfer`: the transform is checked against the declaration, never a source of its generics. */\n    readonly transform?: NoInfer<CollectionTransform<M, (Create extends undefined ? never : CollectionInputOf<M, Create, 'create'>) | (Update extends undefined ? never : CollectionInputOf<M, Update, 'update'>)>>;\n    readonly notifications?: CollectionNotifications;\n    /** Similarity indexes, each a `/<name>` search command on this collection. */\n    readonly similarity?: Readonly<Record<string, SimilarityIndexDeclaration<M>>>;\n}\n\n/** The input selection one operation declares. */\nexport interface CollectionOperationDeclaration {\n    readonly input: CollectionInputSelection;\n}\n\n/**\n * One transform. It runs once per admitted batch, reads as the workspace, and returns one payload\n * per input, in order, or refuses. Returning the payload is how it asks for writes.\n */\nexport type CollectionTransform<M extends ModelDeclaration, Input> = (inputs: ReadonlyArray<Input>, context: Readonly<{\n    /** The stored root row per input, `undefined` on a create. */\n    readonly existing: ReadonlyArray<RowFor<M> | undefined>;\n    /** The reads-only tenant database surface, budgeted to two waves per operation. */\n    readonly db: CollectionTransformDatabase;\n}>) => Effect.Effect<ReadonlyArray<PayloadFor<M, 'create'> | PayloadFor<M, 'update'>>, AuthoredRefusal>;\n\n/** What every lifecycle event carries to its rules. */\nexport interface CollectionLifecycleEvent {\n    readonly event: CollectionNotificationEvent;\n    readonly collection: string;\n    readonly action: 'create' | 'update' | 'delete';\n    /** The ids of the records the operation wrote or held, root first. */\n    readonly ids: ReadonlyArray<string>;\n    /** The user who submitted the operation. */\n    readonly requestor: string;\n    /** The open request, on approval events. */\n    readonly approval?: Readonly<{\n        readonly requestId: string;\n        readonly step: Readonly<{\n            readonly index: number;\n            readonly approvers: ReadonlyArray<string>;\n        }>;\n        readonly decidedBy?: string;\n        readonly reason?: string;\n    }>;\n}\n\n/** The events every collection may notify on, one for each approval-machine transition. */\nexport type CollectionNotificationEvent = 'committed' | 'rejected' | 'approvalStarted' | 'approvalStepRequested' | 'approvalStepApproved' | 'approvalChangesRequested' | 'approvalWithdrawn' | 'approvalSuperseded' | 'approvalConflicted' | 'approvalCompleted';\n\n/** One declared notification rule, typed by the channel it names. */\nexport type CollectionNotificationRule = {\n    readonly [Name in NotificationChannel]: {\n        readonly channel: Name;\n        /** User ids, or `{ team }` for every member of a team — an approval step's approvers are teams. */\n        readonly recipients: (event: CollectionLifecycleEvent) => ReadonlyArray<NotificationRecipient>;\n        readonly message: (event: CollectionLifecycleEvent) => Readonly<{\n            readonly title: string;\n            readonly body: string;\n        }>;\n    };\n}[NotificationChannel];\n\nexport type CollectionNotifications = Readonly<Partial<Record<CollectionNotificationEvent, ReadonlyArray<CollectionNotificationRule>>>>;\n\n/**\n * The notification channels a collection may declare rules on (RFC §4.5), typed per channel.\n *\n * `inbox` is the workspace notification ledger delivered through `Notify`: a recipient is a user\n * id, or `{ team }` — every member of that team at commit time, resolved inside the write's own\n * statement (an approval step's approvers are team names, and so is \"the HR controllers\"). The\n * message is a title and a body. A rule naming a channel absent here is refused at sync; the\n * catalogue is the intersection the deployment grants, and a rule cannot grant itself one.\n */\nexport declare const NotificationRecipient: Schema.Union<readonly [Schema.NonEmptyString, Schema.Struct<{\n    readonly team: Schema.NonEmptyString;\n}>]>;\n\nexport declare const NotificationChannels: {\n    readonly inbox: {\n        readonly recipients: Schema.$Array<Schema.Union<readonly [Schema.NonEmptyString, Schema.Struct<{\n            readonly team: Schema.NonEmptyString;\n        }>]>>;\n        readonly message: Schema.Struct<{\n            readonly title: Schema.NonEmptyString;\n            readonly body: Schema.String;\n        }>;\n    };\n};"
