		{
			"title": "Model columns",
			"body": "/** What an instant-range renderer offers: calendar days, or date-times. */\nexport declare const defineModel: <const TColumns extends Readonly<Record<string, AnyModelFieldBuilder>>>(columns: TColumns, metadata?: ModelMetadata<keyof TColumns & string>) => ModelDeclaration<TColumns>;\n\n/**\n * What a `defineModel` declaration may say about the collection as a whole.\n *\n * Every key here is read by something; an option nothing reads is a lie in the authoring surface, so\n * The authoring surface accepts no `opsGuard`, `replica` or `insertOnly` field: they have no\n * reference anywhere in this package and no declaration in any template — accepting them only bought\n * an author the belief that a flag had an effect.\n *\n * `tests/authoring/metadata-witness.test.ts` holds this interface against the function that reads\n * each key, so a key added here has to name its reader or be listed as knowingly unread.\n */\nexport interface ModelMetadata<Field extends string = string> {\n    readonly description?: string;\n    /**\n     * The column, or columns, that name a record on screen.\n     *\n     * The array form compiles to the ` + ' · ' + ` concatenation `resolveRecordLabel` splits on, so a\n     * label survives term by term when one field is empty rather than collapsing to a uuid.\n     */\n    readonly recordLabel?: string | ReadonlyArray<string>;\n    readonly icon?: string;\n    readonly history?: boolean;\n    readonly indexes?: ReadonlyArray<ModelIndex>;\n    readonly exclusions?: ReadonlyArray<ModelExclusion>;\n    /** One platform-maintained vector over the named fields. See `ModelEmbedding`. */\n    readonly embedding?: ModelEmbedding<Field>;\n}\n\nexport declare const text: (options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\nexport declare const numeric: () => import(\"drizzle-orm/pg-core\").PgNumericNumberBuilder;\n\n/** Owns the only temporal scalar at the authoring boundary. */\nexport declare const instant: (options?: {\n    readonly precision?: InstantPrecision;\n}) => import(\"drizzle-orm/pg-core\").PgTimestampStringBuilder;\n\n/** Owns enums behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const enums: (values: readonly [string, ...string[]], options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\n/** Owns file behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const file: typeof fileColumn;\n\n/** Owns vector behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const vector: (options: {\n    readonly dimensions: number;\n}) => import(\"drizzle-orm/pg-core\").PgVectorBuilder;\n\n/**\n * Declares one logical field that may point at exactly one of the named collections.\n *\n * Tags are the stable application discriminator; collection names are the physical FK targets.\n * The database representation is generated later and never leaks into authored row types.\n */\nexport declare const reference: <const TTargets extends ReferenceTargets>(targets: TTargets) => ReferenceBuilder<TTargets, false, false>;\n\nexport declare const custom: <const Name extends CustomTypeName, const Arguments extends CustomArguments<Name>>(name: Name, ...arguments_: Arguments) => import(\"drizzle-orm/pg-core\").Set$Type<import(\"drizzle-orm/pg-core\").PgJsonbBuilder, CustomColumnValue<Name, Arguments[0]>>;\n\nexport declare const group: <const T extends BoltGroupDefinition>(definition: T) => T;\n\nexport declare const cascade: <T extends object>(relationship: T) => T;\n\nexport declare const setNull: <T extends object>(relationship: T) => T;\n\nexport declare const deferrable: <T extends object>(relationship: T) => T;\n\n/** Owns geolocation behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const geolocation: () => import(\"drizzle-orm/pg-core\").Set$Type<import(\"drizzle-orm/pg-core\").PgJsonbBuilder, {\n    readonly geometry: {\n        readonly lon: number;\n        readonly lat: number;\n    } | null;\n    readonly formatted_address: string;\n    readonly type: \"Point\";\n    readonly srid: number;\n}>;\n\n/** Owns phone behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const phone: (options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\n/**\n * Refuses the operation, and is declared to return `never` explicitly.\n *\n * The annotation is load-bearing, not decoration. TypeScript only treats a call as terminating\n * control flow when the callee is an identifier carrying an **explicit** return type, so without it\n * `if (value == null) refuse('…')` narrows nothing and every use below the guard is\n * `possibly undefined`. The emitted `.d.ts` infers one, which is why a workspace compiling against\n * the published build behaved differently from one compiling against these sources — 32 phantom\n * errors in a single template, none of them the template's fault.\n */\nexport declare const refuse: (message: string) => never;"
		},
		{
			"title": "Policies, approvals, teams",
			"body": "/**\n * A policy: the complete statement of what its holder may do.\n *\n * Four keys, and every one answers a question about *this policy's holders* — whether that holder is\n * a person through a team, an envoy, or an automation. `grants` is what they may touch,\n * `capabilities` is what they may call, `limits` is how much, and the approval on a grant is who has\n * to agree first. Nothing else in the system grants capability.\n *\n * There is no `name`. The filename is the name, exactly as it is for a collection, an app and an\n * envoy, and a restated `name:` is precisely what let five workspaces ship a display-cased string\n * that compiled and matched nothing. There is no field left to disagree with the file.\n */\nexport interface PolicyDefinition<S extends AnySchema = DefaultWorkspaceSchema> {\n    readonly description: string;\n    readonly grants: PolicyGrants<S>;\n    readonly capabilities?: PolicyCapabilities;\n    readonly limits?: PolicyLimits;\n}\n\n/**\n * What write authorization and approval-flow functions may reach: collection reads.\n *\n * Deciding whether a write may proceed or who must sign it is evaluated through the direct\n * `db.<collection>` route.\n */\nexport type PolicyDecisionApi<S extends AnySchema = DefaultWorkspaceSchema> = Readonly<{\n    readonly db: AuthoredReadDatabase<S>;\n    readonly requestor: Readonly<{\n        readonly id: string;\n        readonly userId: string;\n        readonly tenantId: string;\n        readonly email?: string;\n        readonly team?: TeamName;\n        readonly teamPath: ReadonlyArray<TeamName>;\n        readonly admin: boolean;\n    }>;\n}>;\n\nexport type ApprovalFlow = ApprovalReviewFlow | NoApprovalFlow;\n\nexport type ApprovalReviewFlow = Readonly<{\n    readonly _tag: 'Review';\n    readonly stages: ReadonlyArray<ApprovalStage>;\n    readonly thenBy: (first: TeamName, ...others: ReadonlyArray<TeamName>) => ApprovalReviewFlow;\n    readonly [ApprovalFlowBrand]: true;\n}>;\n\nexport type NoApprovalFlow = Readonly<{\n    readonly _tag: 'NoApproval';\n    readonly [ApprovalFlowBrand]: true;\n}>;\n\n/**\n * The shape of `src/access/+teams.ts`: which policies each named team holds.\n *\n * Keys are team names, matched case-insensitively against `team.name`, and free strings on\n * purpose — a team is a row an operator creates from a dashboard, so no compiled union can enumerate\n * them, and this file is where the enumeration comes from. Values are narrowed to *this* workspace's\n * declared policy names, so renaming or deleting a policy breaks the build here, in the map that\n * hands it to people, instead of quietly emptying somebody's authority at run time.\n *\n * The runtime is deliberately more forgiving than this type: a team naming a policy the release does\n * not declare has that name dropped and warned about, never refused, because a row and a release\n * move independently and a workspace must not fall over on a stale string. This check is what makes\n * that tolerance a safety net rather than the only line of defence.\n */\nexport type Teams = Readonly<Record<string, ReadonlyArray<PolicyName>>>;\n\n/** Starts a concrete review flow. Teams listed in one stage are alternatives; stages are sequential. */\nexport declare const approveBy: (first: TeamName, ...others: ReadonlyArray<TeamName>) => ApprovalReviewFlow;\n\n/** Explicitly selects the branch in which this write needs no review. */\nexport declare const noApproval: NoApprovalFlow;"
		},
		{
			"title": "Functions",
			"body": "/** Public read-remote contract that retains the augmented workspace schema in generated types. */\ninterface DefineQueryHandler {\n    <const S extends Schema.Codec<unknown, unknown>, Workspace extends AnySchema = DefaultWorkspaceSchema, Output = unknown, E = never>(definition: AuthoredHandler<S, Workspace, Output, E>): HandlerDefinition<S, Output, Workspace, 'query', E>;\n}\n\n/**\n * Public mutating-remote contract. The literal command discriminant is part of compiler discovery\n * and runtime authorization, while the symbolic default lets each workspace augment its tables.\n */\ninterface DefineCommandHandler {\n    <const S extends Schema.Codec<unknown, unknown>, Workspace extends AnySchema = DefaultWorkspaceSchema, Output = unknown, E = never>(definition: AuthoredHandler<S, Workspace, Output, E>): HandlerDefinition<S, Output, Workspace, 'command', E>;\n}\n\nexport declare const defineQueryHandler: DefineQueryHandler;\n\nexport declare const defineCommandHandler: DefineCommandHandler;"
		}
